return ['domain'=>'wp-knowledge-chat','plural-forms'=>'nplurals=1; plural=0;','language'=>'id_ID','project-id-version'=>'WP Knowledge Chat 0.2.0','pot-creation-date'=>'2026-10-14T16:58:55+00:00','po-revision-date'=>'2026-10-14 00:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['WP Knowledge Chat'=>'WP Knowledge Chat','Inpartner AI Business Consultation Assistant: a floating chat widget that answers visitor questions from approved website content via a separate AI backend.'=>'Inpartner AI Business Consultation Assistant: widget obrolan mengambang yang menjawab pertanyaan pengunjung dari konten situs yang telah disetujui melalui backend AI terpisah.','Inpartner'=>'Inpartner','WP Knowledge Chat Settings'=>'Pengaturan WP Knowledge Chat','Settings'=>'Pengaturan','Chat widget'=>'Widget obrolan','Enable Chatbot'=>'Aktifkan Chatbot','Greeting Messages'=>'Pesan Sapaan','Default Language'=>'Bahasa Default','Language Switcher'=>'Pengalih Bahasa','Browser Language'=>'Bahasa Browser','Contact URL'=>'URL Kontak','Show the chat widget on the public site.'=>'Tampilkan widget obrolan di situs publik.','Shown when the chat opens, in the visitor\'s language. Plain text only (HTML is removed). Maximum %d characters. Leave a field empty to restore its default.'=>'Ditampilkan saat obrolan dibuka, dalam bahasa pengunjung. Hanya teks biasa (HTML dihapus). Maksimal %d karakter. Kosongkan kolom untuk mengembalikan sapaan bawaan.','Interface language and preferred answer language when the visitor has not chosen one. Source content is not altered.'=>'Bahasa antarmuka dan bahasa jawaban yang diutamakan jika pengunjung belum memilih. Konten sumber tidak diubah.','Let visitors switch between English, Bahasa Indonesia and 한국어 in the chat header.'=>'Izinkan pengunjung beralih antara English, Bahasa Indonesia, dan 한국어 di header obrolan.','Start in the visitor\'s browser language when it is supported; otherwise use the default language.'=>'Mulai dengan bahasa browser pengunjung jika didukung; ji