tbot must be checked or unchecked.'=>'Aktifkan Chatbot harus dicentang atau tidak dicentang.','Language Switcher must be checked or unchecked.'=>'Pengalih Bahasa harus dicentang atau tidak dicentang.','Browser Language must be checked or unchecked.'=>'Bahasa Browser harus dicentang atau tidak dicentang.','Greeting message must be text.'=>'Pesan sapaan harus berupa teks.','Default language must be English (en), Indonesian (id) or Korean (ko).'=>'Bahasa default harus Inggris (en), Indonesia (id), atau Korea (ko).','Greeting message is required.'=>'Pesan sapaan wajib diisi.','Greeting message must be %d characters or fewer.'=>'Pesan sapaan maksimal %d karakter.','Contact URL must be an absolute https:// URL on an approved domain (%s), without credentials or a custom port.'=>'URL Kontak harus berupa URL https:// absolut pada domain yang disetujui (%s), tanpa kredensial atau port khusus.','WP Knowledge Chat leads'=>'Permintaan konsultasi WP Knowledge Chat','Backend is not configured.'=>'Backend belum dikonfigurasi.','Index token or backend URL is not configured.'=>'Token indeks atau URL backend belum dikonfigurasi.','Service'=>'Layanan','About'=>'Tentang','Contact'=>'Kontak','FAQ'=>'FAQ','Home'=>'Beranda','Article'=>'Artikel']];
